M.launchChecks = (function () {
  const module = { exports: {} };
/**
 * launchChecks.js – Module 5 pre-launch checks and the launch plan.
 */
function domainOf(email) {
  return String(email || '').split('@')[1] || '';
}

/**
 * ctx: {campaign, leads, emails, blocklist, otherLiveContactedDomains, gmailOk, testMode, isBlocked}
 * returns {ok, failures:[{check, count, detail}], approvedLeads}
 */
function runPrelaunchChecks(ctx) {
  const failures = [];
  const minLeads = ctx.testMode ? 5 : 20;
  const approved = (ctx.leads || []).filter((l) => l.status === 'Approved');
  if (approved.length < minLeads) failures.push({ check: `At least ${minLeads} Approved leads`, count: approved.length, detail: `${approved.length} approved` });
  const emailsByLead = {};
  (ctx.emails || []).forEach((e) => {
    const id = Array.isArray(e.lead) ? e.lead[0] : e.lead_record_id || e.lead;
    (emailsByLead[id] = emailsByLead[id] || []).push(e);
  });
  const badQuality = approved.filter((l) => {
    const es = emailsByLead[l.id] || [];
    // a sequence approved by a person in the Control Center (after editing) counts as passed (approved_by set)
    return es.length !== 4 || es.some((e) => !e.approved || (Number(e.quality_score) < 80 && !e.approved_by));
  });
  if (badQuality.length) failures.push({ check: 'Every sequence passed the AI quality check', count: badQuality.length, detail: badQuality.map((l) => l.company_name).join(', ') });
  const blocked = approved.filter((l) => ctx.isBlocked(l.email, ctx.blocklist) || ctx.isBlocked('x@' + (l.domain || domainOf(l.email)), ctx.blocklist));
  if (blocked.length) failures.push({ check: 'No lead on the Blocklist', count: blocked.length, detail: blocked.map((l) => l.email).join(', ') });
  const other = new Set((ctx.otherLiveContactedDomains || []).map((d) => String(d).toLowerCase()));
  const clash = approved.filter((l) => other.has(String(l.domain || domainOf(l.email)).toLowerCase()));
  if (clash.length) failures.push({ check: 'No lead contacted in another Live campaign', count: clash.length, detail: clash.map((l) => l.domain).join(', ') });
  if (!ctx.gmailOk) failures.push({ check: 'Gmail credential works', count: 1, detail: ctx.gmailError || 'Gmail profile check failed' });
  return { ok: failures.length === 0, failures, approvedLeads: approved };
}

/** sequence_step=1, next_send_at = next slot, subject A/B alternately. */
function buildLaunchPlan(approvedLeads, firstSlotIso, campaign) {
  return approvedLeads.map((l, i) => ({
    id: l.id,
    fields: {
      sequence_step: 1,
      next_send_at: firstSlotIso,
      subject_variant: i % 2 === 0 ? 'A' : 'B',
    },
  }));
}

function failureText(campaignName, failures) {
  return `:no_entry: Campaign *${campaignName}* was not launched. ${failures.length} check(s) failed:\n` +
    failures.map((f) => `• ${f.check} – ${f.detail} (${f.count})`).join('\n') + '\nStatus is back to Ready.';
}

const launchChecksApi = { runPrelaunchChecks, buildLaunchPlan, failureText };
if (typeof module !== 'undefined' && module.exports) module.exports = launchChecksApi;

  return module.exports;
})();

M.guard = (function () {
  const module = { exports: {} };
/**
 * guard.js – the safety guard that runs right before every email-sending node.
 * - Blocks the run (throws) if any recipient is not on TEST_RECIPIENT_ALLOWLIST.
 * - An empty allowlist blocks everything in test mode.
 * - DEMO_MODE: rewrites To to TEST_PROSPECT_EMAIL (internal notifications: to SENDER_EMAIL), drops Cc/Bcc and marks
 *   the message as a test with the header X-Nexsale-Test (no visible [TEST] in the subject – user's decision 2026-11-15).
 * - Real mode (DEMO_MODE=false) additionally needs ALLOW_REAL_SENDING=true, otherwise it blocks.
 */
class GuardError extends Error {
  constructor(message, details) {
    super(message);
    this.name = 'GuardError';
    this.details = details || {};
  }
}

function norm(e) {
  return String(e || '').trim().toLowerCase();
}

function splitAddresses(v) {
  if (!v) return [];
  const list = Array.isArray(v) ? v : String(v).split(/[,;]/);
  return list
    .map((x) => {
      const m = String(x).match(/<([^>]+)>/);
      return norm(m ? m[1] : x);
    })
    .filter(Boolean);
}

const INTERNAL_PURPOSES = ['internal', 'report'];

function guardEmail(msg, cfg) {
  if (!msg || typeof msg !== 'object') throw new GuardError('Guard: no message');
  if (!cfg || typeof cfg !== 'object') throw new GuardError('Guard: no config');
  const original = { to: splitAddresses(msg.to), cc: splitAddresses(msg.cc), bcc: splitAddresses(msg.bcc) };
  if (!original.to.length) throw new GuardError('Guard: message has no recipient');
  const out = Object.assign({}, msg);
  if (cfg.demoMode) {
    if (!cfg.testProspectEmail) throw new GuardError('Guard: DEMO_MODE is on but TEST_PROSPECT_EMAIL is empty');
    // internal notifications (Campaign ready, weekly report) inform the team only – never the test prospect inbox
    const internal = INTERNAL_PURPOSES.includes(String(msg.purpose || ''));
    out.to = internal && cfg.senderEmail ? cfg.senderEmail : cfg.testProspectEmail;
    out.cc = '';
    out.bcc = '';
    out.subject = String(msg.subject || '').replace(/^\s*\[TEST\]\s*/, '');
    out.testMarker = true; // becomes the header X-Nexsale-Test: true
    out.original_to = original.to.join(', ');
  } else if (!cfg.allowRealSending) {
    throw new GuardError('Guard: DEMO_MODE is off but ALLOW_REAL_SENDING is not true – blocked', { to: original.to });
  }
  const allow = (cfg.allowlist || []).map(norm);
  const finalRecipients = [].concat(splitAddresses(out.to), splitAddresses(out.cc), splitAddresses(out.bcc));
  if (cfg.demoMode || allow.length) {
    if (!allow.length) throw new GuardError('Guard: TEST_RECIPIENT_ALLOWLIST is empty – every send is blocked');
    const bad = finalRecipients.filter((r) => !allow.includes(r));
    if (bad.length) throw new GuardError('Guard: recipient not on allowlist: ' + bad.join(', '), { blocked: bad });
  }
  out.guard = { passed: true, demoMode: !!cfg.demoMode, recipients: finalRecipients, checkedAt: new Date().toISOString() };
  return out;
}

/** Blocklist check: entries are {value} (email or domain) or plain strings. */
function isBlocked(email, blocklist) {
  const e = norm(email);
  if (!e) return false;
  const domain = e.split('@')[1] || '';
  return (blocklist || []).some((entry) => {
    const v = norm(typeof entry === 'string' ? entry : entry && (entry.value || entry.email || entry.domain));
    if (!v) return false;
    if (v.includes('@')) return v === e;
    return v === domain || domain.endsWith('.' + v);
  });
}

const guardApi = { GuardError, guardEmail, isBlocked, splitAddresses, INTERNAL_PURPOSES };
if (typeof module !== 'undefined' && module.exports) module.exports = guardApi;

  return module.exports;
})();

